(function(){const ARTICLE_SELECTOR='article.md-content__inner';const EXCLUDE_SELECTOR='#waline, .md-source-file, .md-content__button, .site-block-hint';const BLOCK_SELECTOR=['h1','h2','h3','h4','h5','h6','p','li','dl','hr','blockquote','div.highlight','.md-typeset__table','.mermaid','div.arithmatex','details','summary','.admonition','.admonition-title','.tabbed-labels'].join(',');const ATOMIC_SELECTOR='div.highlight, .md-typeset__table, .mermaid, div.arithmatex, hr';const MEDIA_QUERY='(hover: hover) and (pointer: fine) and (min-width: 1200px)';const HIDE_DELAY=180;const GAP=6;const ICONS={text:'<span class="site-block-hint__glyph">T</span>',code:'<span class="site-block-hint__glyph site-block-hint__glyph--code">&lt;/&gt;</span>',formula:'<span class="site-block-hint__glyph">Σ</span>',ul:'<svg viewBox="0 0 24 24"><circle cx="5" cy="7" r="1.4"/><circle cx="5" cy="12" r="1.4"/><circle cx="5" cy="17" r="1.4"/><path d="M9.5 7h10M9.5 12h10M9.5 17h10"/></svg>',ol:'<svg viewBox="0 0 24 24"><path d="M4 5.5h1.5V10M4 10h3M4 14.5h3l-3 4h3M10 7h10M10 12h10M10 17h10"/></svg>',task:'<svg viewBox="0 0 24 24"><rect x="4" y="4" width="16" height="16" rx="3"/><path d="m8 12 3 3 5-6"/></svg>',quote:'<svg viewBox="0 0 24 24"><path d="M5 5v14M9.5 8h9.5M9.5 12h9.5M9.5 16h6"/></svg>',table:'<svg viewBox="0 0 24 24"><rect x="3.5" y="5" width="17" height="14" rx="2"/><path d="M3.5 10h17M3.5 14.5h17M10 5v14"/></svg>',image:'<svg viewBox="0 0 24 24"><rect x="3.5" y="5" width="17" height="14" rx="2"/><circle cx="9" cy="10" r="1.6"/><path d="m4 17 5-4.5 4 3.5 2.5-2 4.5 3.5"/></svg>',diagram:'<svg viewBox="0 0 24 24"><rect x="9" y="3.5" width="6" height="5" rx="1"/><rect x="3.5" y="15.5" width="6" height="5" rx="1"/><rect x="14.5" y="15.5" width="6" height="5" rx="1"/><path d="M12 8.5v3.5M6.5 15.5V12h11v3.5"/></svg>',admonition:'<svg viewBox="0 0 24 24"><rect x="3.5" y="4.5" width="17" height="15" rx="2.5"/><path d="M12 8.5v4.5M12 16v.01"/></svg>',details:'<svg viewBox="0 0 24 24"><path d="m6 9 6 6 6-6"/></svg>',tabs:'<svg viewBox="0 0 24 24"><path d="M3.5 19.5v-12a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2h7a2 2 0 0 1 2 2v8z"/></svg>',hr:'<svg viewBox="0 0 24 24"><path d="M4 12h16"/></svg>',dl:'<svg viewBox="0 0 24 24"><path d="M4 6.5h9M7.5 11h12.5M4 15.5h9M7.5 20h12.5"/></svg>'};const GRIP='<svg class="site-block-hint__grip" viewBox="0 0 8 14"><circle cx="2" cy="2" r="1.1"/><circle cx="6" cy="2" r="1.1"/><circle cx="2" cy="7" r="1.1"/><circle cx="6" cy="7" r="1.1"/><circle cx="2" cy="12" r="1.1"/><circle cx="6" cy="12" r="1.1"/></svg>';const mediaQuery=window.matchMedia(MEDIA_QUERY);let marker=null;let currentBlock=null;let hideTimer=null;let lastPointer=null;let scrollFrame=0;function getMarker(){if(marker&&document.body.contains(marker)){return marker;}
marker=document.createElement('div');marker.className='site-block-hint';marker.setAttribute('aria-hidden','true');marker.title='点击选中整个块';marker.innerHTML='<span class="site-block-hint__icon"></span>'+GRIP;marker.addEventListener('mousedown',(event)=>{event.preventDefault();});marker.addEventListener('click',(event)=>{event.preventDefault();event.stopPropagation();if(currentBlock){selectBlock(currentBlock);}});document.body.appendChild(marker);return marker;}
function isImageParagraph(el){return el.tagName==='P'&&el.textContent.trim()===''&&el.querySelector('img');}
function findBlock(target,article){let candidate=null;for(let el=target;el&&el!==article;el=el.parentElement){if(el.matches(EXCLUDE_SELECTOR)){return null;}
if(!el.matches(BLOCK_SELECTOR)){continue;}
if(el.matches(ATOMIC_SELECTOR)||isImageParagraph(el)){return el;}
if(!candidate){candidate=el;}}
if(!candidate){return null;}
const parent=candidate.parentElement;if(candidate.tagName==='P'&&parent&&(parent.tagName==='LI'||parent.tagName==='BLOCKQUOTE')){return parent;}
if(candidate.matches('.admonition-title')){return candidate.closest('.admonition, details')||candidate;}
if(candidate.tagName==='SUMMARY'){return candidate.parentElement;}
if(candidate.matches('.tabbed-labels')){return candidate.closest('.tabbed-set')||candidate;}
return candidate;}
function getIcon(block){const tag=block.tagName;if(/^H[1-6]$/.test(tag)){return'<span class="site-block-hint__glyph site-block-hint__glyph--heading">H'+tag.charAt(1)+'</span>';}
if(tag==='LI'){if(block.classList.contains('task-list-item'))return ICONS.task;return block.parentElement&&block.parentElement.tagName==='OL'?ICONS.ol:ICONS.ul;}
if(tag==='DETAILS')return ICONS.details;if(tag==='BLOCKQUOTE')return ICONS.quote;if(tag==='HR')return ICONS.hr;if(tag==='DL')return ICONS.dl;if(block.matches('div.highlight'))return ICONS.code;if(block.matches('.md-typeset__table'))return ICONS.table;if(block.matches('.mermaid'))return ICONS.diagram;if(block.matches('div.arithmatex'))return ICONS.formula;if(block.matches('.admonition'))return ICONS.admonition;if(block.matches('.tabbed-set'))return ICONS.tabs;if(isImageParagraph(block))return ICONS.image;return ICONS.text;}
function getFirstLineOffset(block,markerHeight){if(block.matches(ATOMIC_SELECTOR)||block.matches('.admonition, details, .tabbed-set, blockquote, dl')){return 6;}
const style=window.getComputedStyle(block);let lineHeight=parseFloat(style.lineHeight);if(Number.isNaN(lineHeight)){lineHeight=parseFloat(style.fontSize)*1.2;}
return parseFloat(style.paddingTop)+(lineHeight-markerHeight)/2;}
function showFor(block){window.clearTimeout(hideTimer);hideTimer=null;const el=getMarker();if(block!==currentBlock){currentBlock=block;el.querySelector('.site-block-hint__icon').innerHTML=getIcon(block);}
const anchor=block.tagName==='LI'&&block.parentElement?block.parentElement:block;const rect=block.getBoundingClientRect();const left=anchor.getBoundingClientRect().left;const markerRect=el.getBoundingClientRect();const top=rect.top+getFirstLineOffset(block,markerRect.height);el.style.left=(left+window.scrollX-markerRect.width-GAP)+'px';el.style.top=(top+window.scrollY)+'px';el.classList.add('is-visible');}
function hide(){window.clearTimeout(hideTimer);hideTimer=null;currentBlock=null;if(marker){marker.classList.remove('is-visible');}}
function getSelectionTarget(block){if(block.matches('div.highlight')){return block.querySelector('td.code code, pre > code')||block;}
return block;}
function selectBlock(block){const selection=window.getSelection();if(!selection){return;}
const range=document.createRange();range.selectNodeContents(getSelectionTarget(block));selection.removeAllRanges();selection.addRange(range);}
function scheduleHide(){if(hideTimer||!currentBlock){return;}
hideTimer=window.setTimeout(hide,HIDE_DELAY);}
function handlePoint(target){if(!mediaQuery.matches||!target||!(target instanceof Element)){scheduleHide();return;}
if(marker&&marker.contains(target)){window.clearTimeout(hideTimer);hideTimer=null;return;}
const article=target.closest(ARTICLE_SELECTOR);const block=article?findBlock(target,article):null;if(block){showFor(block);}else{scheduleHide();}}
document.addEventListener('mousemove',(event)=>{lastPointer={x:event.clientX,y:event.clientY};handlePoint(event.target);},{passive:true});document.addEventListener('mouseleave',hide);window.addEventListener('scroll',()=>{if(!lastPointer||scrollFrame){return;}
scrollFrame=window.requestAnimationFrame(()=>{scrollFrame=0;handlePoint(document.elementFromPoint(lastPointer.x,lastPointer.y));});},{passive:true});window.addEventListener('resize',hide);if(typeof mediaQuery.addEventListener==='function'){mediaQuery.addEventListener('change',hide);}
if(typeof document$!=='undefined'&&typeof document$.subscribe==='function'){document$.subscribe(hide);}})();